package br.com.sussmartcare.patientregistry.infrastructure.outbox; import com.fasterxml.jackson.databind.ObjectMapper; import java.time.*; import java.util.*; import org.slf4j.MDC; import org.springframework.stereotype.Component; @Component public class EventOutbox {private final OutboxRepository repo;private final ObjectMapper mapper;public EventOutbox(OutboxRepository r,ObjectMapper m){repo=r;mapper=m;}public void append(String topic,String key,Object data){try{var e=new Envelope(UUID.randomUUID(),topic,key,Instant.now(),"1",MDC.get("correlationId"),MDC.get("traceId"),data);repo.save(new OutboxEvent(topic,key,mapper.writeValueAsString(e)));}catch(Exception ex){throw new IllegalStateException("Falha serializando evento",ex);}}public record Envelope(UUID eventId,String eventType,String aggregateId,Instant occurredAt,String schemaVersion,String correlationId,String traceId,Object data){}}